@Injectable({ providedIn: 'root' })
export class MessagesService {
  private nextId = 0;
  private readonly _messages = signal<AppMessage[]>([]);
  readonly messages = this._messages.asReadonly();

  addMessage(text: string, style: MessageStyle, closeDelayMs: number = 5000): AppMessage {
    const message: AppMessage = { id: this.nextId++, text, style, closeDelayMs };
    this._messages.update(list => [...list, message]);
    if (closeDelayMs > 0) {
      setTimeout(() => this.close(message.id), closeDelayMs);
    }
    return message;
  }

  success(text: string) { this.addMessage(text, MessageStyle.SUCCESS); }
  error(text: string) { this.addMessage(text, MessageStyle.ERROR); }

  close(id: number) { this._messages.update(list => list.filter(m => m.id !== id)); }
}
