 * debug ids into DOM ids.
 *
 * GWT renders `debugId="X"` as the DOM id `gwt-debug-X` (`UIObject.DEBUG_ID_PREFIX`
 * + debug id). The end-to-end tests locate elements through those ids
 * (`ByDebugId`), so the migrated widgets keep producing the same ids.
 */
export const DEBUG_ID_PREFIX = 'gwt-debug-';

export class DebugIds {
    static readonly DBG_DOM = 'dom';

    static readonly DBG_MENUBAR = 'menubar';
    static readonly DBG_LINK_TO_LOGIN = 'linkToLogin';
    static readonly DBG_USERNAME = 'username';
    static readonly DBG_PASSWORD = 'password';
