    static readonly DBG_CARS = 'cars';
    static readonly DBG_CARS_TAB_PANEL = 'cars-tab-panel';
    static readonly DBG_CAR_CREATE = 'carCreate';
    static readonly DBG_CAR_MODEL_INPUT = 'car-model-input';
    static readonly DBG_CAR_MANUFACTURER_INPUT = 'car-manufacturer-input';
    static readonly DBG_CAR_PROPERTIES_EDITOR = 'car-properties-editor';
    static readonly DBG_CAR_SAVE = 'car-save';
    static readonly DBG_CAR_CLOSE = 'car-close';

    static readonly DBG_MANUFACTURERS = 'manufacturers';
    static readonly DBG_CREATE_MANUFACTURER = 'create-manufacturer';
    static readonly DBG_MANUFACTURER_EDITOR = 'manufacturer-editor';
    static readonly DBG_MANUFACTURER_INPUT = 'manufacturer-input';
    static readonly DBG_MANUFACTURER_SAVE = 'manufacturer-save';
    static readonly DBG_MANUFACTURER_CLOSE = 'manufacturer-close';

    static readonly DBG_RATINGS = 'ratings';
    static readonly DBG_RATING_INPUT = 'ratingInput';
    static readonly DBG_RATING_CREATE = 'ratingCreate';
    static readonly DBG_RATING_SAVE = 'ratingSave';

    static readonly DBG_REPORTS = 'reports';

    // Not declared in DebugIds.java: the GWT MessageWidget assigns these debug ids
    // directly (HTMLPanel.ensureDebugId(messageBox.getElement(), "successMessage")).
    static readonly DBG_SUCCESS_MESSAGE = 'successMessage';
