import { Component, inject } from '@angular/core';
import { Router, RouterLink, RouterLinkActive } from '@angular/router';

import { NameTokens } from '../../name-tokens';
import { ApiService, httpErrorMessage } from '../../core/api.service';
import { MessagesService } from '../../core/messages.service';

/** One entry of the menubar (`HeaderView.ui.xml`'s `InlineHyperlink`s). */
export interface MenuLink {
    /** The GWT history token used as route path / `href`. */
    token: string;
    label: string;
}

/**
 * Mirrors `HeaderView` — the application header with the menubar used to move
 * between the screens. Links keep the GWT history tokens in their `href`
 * (`#manufacturer`, `#rating`, ...), so navigation still works through the
 * menubar like in the GWT application.
 */
@Component({
    selector: 'app-header',
    standalone: true,
    imports: [RouterLink, RouterLinkActive],
    templateUrl: './header.component.html',
    styleUrl: './header.component.css',
})
export class HeaderComponent {
    private readonly api = inject(ApiService);
    private readonly router = inject(Router);
    private readonly messages = inject(MessagesService);

    protected readonly links: MenuLink[] = [
        { token: NameTokens.MANUFACTURER, label: 'Manufacturers' },
        { token: NameTokens.CARS, label: 'Cars' },
        { token: NameTokens.RATING, label: 'Ratings' },
        { token: NameTokens.REPORT, label: 'Reports' },
        { token: NameTokens.STATS, label: 'Statistics' },
    ];

    /** Mirrors `HeaderPresenter#logout` — `SessionResource#logout`. */
    protected logout(): void {
        this.api.logout().subscribe({
            next: () => this.router.navigate(['/', NameTokens.getOnLoginDefaultPage()]),
            error: error => this.messages.error(httpErrorMessage(error)),
        });
    }
}

