import { Routes } from '@angular/router';

import { NameTokens } from './name-tokens';
import { ManufacturersComponent } from './manufacturer/manufacturers.component';
import { RatingsComponent } from './rating/ratings.component';
import { ReportsComponent } from './report/reports.component';
import { NotMigratedComponent } from './not-migrated.component';

/**
 * The migrated places. Route paths are the GWT history tokens
 * (`NameTokens.java`), served with hash-based routing so the browser URLs look
 * like the GWT ones (`#manufacturer`, `#rating`, `#report`).
 */
export const routes: Routes = [
    {
        path: '',
        pathMatch: 'full',
        redirectTo: NameTokens.getOnLoginDefaultPage(),
    },
    {
        path: NameTokens.MANUFACTURER,
        component: ManufacturersComponent,
        title: 'Manufacturers',
    },
    {
        path: NameTokens.RATING,
        component: RatingsComponent,
        title: 'Ratings',
    },
    {
        path: NameTokens.REPORT,
        component: ReportsComponent,
        title: 'Reports',
    },
    {
        path: NameTokens.CARS,
        component: NotMigratedComponent,
        data: { screenTitle: 'Cars' },
        title: 'Cars',
    },
    {
        path: NameTokens.STATS,
        component: NotMigratedComponent,
        data: { screenTitle: 'Statistics' },
        title: 'Statistics',
    },
    // Unknown places (e.g. the login or detail places of the GWT application)
    // fall back to the default page.
    {
        path: '**',
        redirectTo: NameTokens.getOnLoginDefaultPage(),
    },
];

