/* Global styles. Component styles belong in the components. */
body { font-family: Arial, Helvetica, sans-serif; margin: 0; }

/*
 * Styles shared by the migrated screens, mirroring the global stylesheet of the
 * GWT application (AppResources styles.css / header.css) and the popup styling
 * of the GWT PopupPanel.
 */

/* Used like the GWT views use their clear/float helpers. */
.clear { clear: both; }
.float-left { float: left; }
.float-right { float: right; }

/* Mirrors the .bigTitle style of the GWT application. */
.big-title {
    color: #545454;
    padding-bottom: 2px;
    border-bottom: 1px solid #dadada;
}

.big-title h2 {
    font-weight: normal;
    float: left;
    font-size: 25px;
    margin: 0;
    padding: 0;
}

.big-title div {
    float: right;
}

/* Mirrors the @sprite .addAction style (a small "add" action button). */
.add-action {
    width: 26px;
    height: 26px;
    border: none;
    border-radius: 13px;
    background-color: #45a0ec;
    color: #ffffff;
    font-size: 18px;
    line-height: 26px;
    padding: 0;
    cursor: pointer;
}

.add-action:hover {
    background-color: #1d6098;
}

/* The CellTable look of the GWT application. */
.data-table {
    width: 100%;
    border-collapse: collapse;
}

.data-table th,
.data-table td {
    text-align: left;
    padding: 6px 10px;
    border-bottom: 1px solid #eaeaea;
}

.data-table th {
    background-color: #f5f5f5;
    border-bottom: 1px solid #dadada;
    font-weight: bold;
}

.data-table tbody tr:hover {
    background-color: #fafafa;
}

.data-table td button {
    padding: 3px 10px;
    cursor: pointer;
}

/* Mirrors the .gwt-PopupPanel style (popup chrome + modal glass). */
.popup-glass {
    position: fixed;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    z-index: 100;
    background-color: black;
    opacity: 0.3;
}

.popup {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    z-index: 101;
    background-color: #ffffff;
    padding: 10px;
    box-shadow: 0 0 5px #888;
}

.popup .editor {
    min-width: 260px;
}

.popup .form-row {
    margin: 8px 0;
}

.popup .form-row span {
    display: inline-block;
    min-width: 90px;
}

.popup .form-actions {
    margin-top: 14px;
    text-align: right;
}

.popup .form-actions button {
    margin-left: 8px;
    padding: 4px 14px;
    cursor: pointer;
}

