import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.chrome.ChromeOptions;

public class DebugDriver {
    public static void main(String[] args) throws Exception {
        System.setProperty("webdriver.chrome.driver", "/tmp/e2e-verify/drivers/chromedriver");

        ChromeOptions options = new ChromeOptions();
        options.setBinary("/usr/bin/chromium");
        options.addArguments("--headless=new", "--no-sandbox", "--disable-dev-shm-usage",
                "--disable-gpu", "--window-size=1280,900");

        WebDriver driver = new ChromeDriver(options);
        try {
            driver.get("http://127.0.0.1:8888/ng/#manufacturer");
            Thread.sleep(3000);
            System.out.println("URL: " + driver.getCurrentUrl());
            System.out.println("TITLE: " + driver.getTitle());
            System.out.println("has dom marker: " + !driver.findElements(By.id("gwt-debug-dom")).isEmpty());
            System.out.println("has menubar: " + !driver.findElements(By.id("gwt-debug-menubar")).isEmpty());
            System.out.println("has manufacturers table: "
                    + !driver.findElements(By.id("gwt-debug-manufacturers")).isEmpty());
            System.out.println("rows: "
                    + driver.findElements(By.cssSelector("#gwt-debug-manufacturers tbody tr")).size());
            System.out.println("menubar links:");
            for (org.openqa.selenium.WebElement link :
                    driver.findElements(By.cssSelector("#gwt-debug-menubar a"))) {
                System.out.println("  " + link.getAttribute("href") + " -> " + link.getText());
            }
            System.out.println("---- page source head ----");
            String src = driver.getPageSource();
            System.out.println(src.substring(0, Math.min(2000, src.length())));
        } finally {
            driver.quit();
        }
    }
}

