import org.openqa.selenium.By;
import org.openqa.selenium.JavascriptExecutor;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.chrome.ChromeOptions;

public class DebugDriver2 {
    public static void main(String[] args) throws Exception {
        System.setProperty("webdriver.chrome.driver", "/tmp/e2e-verify/drivers/chromedriver");

        ChromeOptions options = new ChromeOptions();
        options.setBinary("/usr/bin/chromium");
        options.addArguments("--headless=new", "--no-sandbox", "--disable-dev-shm-usage",
                "--disable-gpu", "--window-size=1280,900");

        WebDriver driver = new ChromeDriver(options);
        JavascriptExecutor js = (JavascriptExecutor) driver;
        try {
            driver.get("http://127.0.0.1:8888/ng/#manufacturer");
            Thread.sleep(3000);
            System.out.println("URL: " + driver.getCurrentUrl());
            System.out.println("hash: " + js.executeScript("return location.hash"));
            System.out.println("gwtParse calls: " + js.executeScript("return window.__gwtParse"));
            System.out.println("gwtSerialize calls: " + js.executeScript("return window.__gwtSerialize"));
            System.out.println("manufacturer table rows: "
                    + driver.findElements(By.cssSelector("#gwt-debug-manufacturers tbody tr")).size());
            System.out.println("first link href: "
                    + driver.findElement(By.cssSelector("#gwt-debug-menubar a")).getAttribute("href"));
        } finally {
            driver.quit();
        }
    }
}

