// injector beat the token's own ɵprov (providedIn root, useFactory)?
import {
    createEnvironmentInjector,
    Injector,
    inject,
} from '/work/node_modules/@angular/core/fesm2022/core.mjs';
import { ɵɵdefineInjectable as defineInjectable } from '/work/node_modules/@angular/core/fesm2022/core.mjs';

class DefaultImpl {
    whoami() { return 'default'; }
}

class Token {
    static { this.ɵprov = defineInjectable({ token: Token, factory: () => new DefaultImpl(), providedIn: 'root' }); }
}

class Sub extends Token {
    whoami() { return 'sub'; }
}

const injector = createEnvironmentInjector(
    [
        { provide: Token, useClass: Sub },
        {
            provide: 'PROBE',
            useFactory: () => {
                const resolved = inject(Token);
                return () => resolved.whoami();
