    [
        wrapper([
            { provide: 'ROUTERISH', useValue: 'router' },
        ]),
        { provide: Token, useClass: Sub },
    ],
    new Injector(),
    'test2',
);
console.log('nested-wrapper case via get():', injector2.get(Token).whoami());

// And the flipped order: wrapper AFTER the explicit provider.
const injector3 = createEnvironmentInjector(
    [
        { provide: Token, useClass: Sub },
        wrapper([
            { provide: 'ROUTERISH', useValue: 'router' },
        ]),
    ],
    new Injector(),
