import org.openqa.selenium.By;
import org.openqa.selenium.JavascriptExecutor;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.chrome.ChromeOptions;
import org.openqa.selenium.support.ui.ExpectedConditions;
import org.openqa.selenium.support.ui.WebDriverWait;

public class DebugDriver3 {
    static WebDriver driver;

    public static void main(String[] args) throws Exception {
        System.setProperty("webdriver.chrome.driver", "/tmp/e2e-verify/drivers/chromedriver");

        ChromeOptions options = new ChromeOptions();
        options.setBinary("/usr/bin/chromium");
        options.addArguments("--headless=new", "--no-sandbox", "--disable-dev-shm-usage",
                "--disable-gpu", "--window-size=1280,900");

        driver = new ChromeDriver(options);
        WebDriverWait wait = new WebDriverWait(driver, 20);
        JavascriptExecutor js = (JavascriptExecutor) driver;
        try {
            // 1. message auto-hide after ~5s
            driver.get("http://127.0.0.1:8888/ng/#manufacturer");
            wait.until(ExpectedConditions.visibilityOfElementLocated(By.id("gwt-debug-manufacturers")));
            driver.findElement(By.id("gwt-debug-create-manufacturer")).click();
            WebElement input = wait.until(ExpectedConditions.visibilityOfElementLocated(By.id("gwt-debug-manufacturer-input")));
            input.clear();
            input.sendKeys("AutoHideTest");
            driver.findElement(By.id("gwt-debug-manufacturer-save")).click();

            WebElement message = wait.until(
                    ExpectedConditions.visibilityOfElementLocated(By.id("gwt-debug-successMessage")));
            System.out.println("success message visible: " + message.getText());
            Thread.sleep(6500);
            System.out.println("message auto-hidden after ~6.5s: "
                    + driver.findElements(By.id("gwt-debug-successMessage")).isEmpty());

            // 2. message close X removes the element (fresh message)
            driver.findElement(By.id("gwt-debug-create-manufacturer")).click();
            wait.until(ExpectedConditions.visibilityOfElementLocated(By.id("gwt-debug-manufacturer-input")));
            driver.findElement(By.id("gwt-debug-manufacturer-close")).click();
            System.out.println("close button hides editor: "
                    + driver.findElements(By.id("gwt-debug-manufacturer-editor")).isEmpty());

            // 3. cancel delete (window.confirm returns false)
            js.executeScript("window.confirm = function(msg){ window.__confirmMsg = msg; return false; };");
            driver.findElement(By.cssSelector("#gwt-debug-manufacturers tbody tr:first-child td:last-child button")).click();
            Thread.sleep(1500);
            System.out.println("confirm message: " + js.executeScript("return window.__confirmMsg"));
            System.out.println("rows unchanged after cancel: "
                    + driver.findElements(By.cssSelector("#gwt-debug-manufacturers tbody tr")).size());

            // 4. logout button + error message paths
            js.executeScript("window.confirm = function(msg){ return true; };");
            driver.findElement(By.id("gwt-debug-logout")).click();
            try {
                WebElement err = wait.until(ExpectedConditions.visibilityOfElementLocated(By.id("gwt-debug-errorMessage")));
                System.out.println("logout produced error message (endpoint state): " + err.getText());
            } catch (Exception e) {
                System.out.println("logout produced no error message");
            }
            System.out.println("still on url: " + driver.getCurrentUrl());
        } finally {
            driver.quit();
        }
    }
}

